/* @component: tabs */
(function () {
  if (window.__tabsMultiInit) return;
  window.__tabsMultiInit = true;

  function isOwnPane(pane) {
    const owner = pane.closest('.tabs');
    return owner && !owner.classList.contains('tab-uno');
  }

  function prepPane(pane) {
    pane.style.display = 'block';
    pane.style.overflow = 'hidden';
    pane.style.transition = 'height 0.3s ease';
  }

  function initPanes() {
    document.querySelectorAll('.tabs:not(.tab-uno) .tabs__pane').forEach(function (pane) {
      if (!isOwnPane(pane) || pane.dataset.tabsInit === 'true') return;
      pane.dataset.tabsInit = 'true';
      prepPane(pane);
      pane.style.height = pane.classList.contains('_is-active') ? 'auto' : '0px';
    });
  }

  function openPane(pane) {
    prepPane(pane);
    const start = pane.offsetHeight;
    pane.style.height = start + 'px';
    pane.classList.add('_is-active');
    pane.offsetHeight;
    const target = pane.scrollHeight;
    pane.style.height = start === target ? 'auto' : target + 'px';
  }

  function closePane(pane) {
    prepPane(pane);
    const start = pane.offsetHeight;
    pane.style.height = start + 'px';
    pane.classList.remove('_is-active');
    pane.offsetHeight;
    pane.style.height = '0px';
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPanes);
  } else {
    initPanes();
  }
  setTimeout(initPanes, 300);

  document.addEventListener('transitionend', function (e) {
    if (e.propertyName === 'height' && e.target.classList.contains('tabs__pane') && isOwnPane(e.target)) {
      if (e.target.classList.contains('_is-active')) {
        e.target.style.height = 'auto';
      }
    }
  });

  document.addEventListener('click', function (e) {
    document.querySelectorAll('.tabs:not(.tab-uno)').forEach(function (root) {
      if (!root.contains(e.target)) {
        root.querySelectorAll('.tabs__btn._is-active').forEach(function (b) {
          if (b.closest('.tabs') === root) b.classList.remove('_is-active');
        });
        root.querySelectorAll('.tabs__pane._is-active').forEach(function (p) {
          if (p.closest('.tabs') === root) closePane(p);});
      }
    });

    const btn = e.target.closest('.tabs__btn');
    if (!btn) return;
    const directTabs = btn.closest('.tabs');
    if (!directTabs || directTabs.classList.contains('tab-uno')) return;

    e.preventDefault();

    const btns = Array.from(directTabs.querySelectorAll('.tabs__btn'))
      .filter(function (b) { return b.closest('.tabs') === directTabs; });
    const panes = Array.from(directTabs.querySelectorAll('.tabs__pane'))
      .filter(function (p) { return p.closest('.tabs') === directTabs; });

    const idx = btns.indexOf(btn);
    const isActive = btn.classList.contains('_is-active');

    btns.forEach(function (b, i) {
      b.classList.remove('_is-active');
      if (panes[i] && panes[i].classList.contains('_is-active')) {
        closePane(panes[i]);
      }
    });

    if (!isActive) {
      btn.classList.add('_is-active');
      if (panes[idx]) openPane(panes[idx]);
    }
  });
})();
/* @end: tabs */
